                <h1>Sign in!</h1>
            </header>

            <div class="input-columns">  

              <div class="input-section login-input-groups">

                <div class="input-container">
                    <label for="userNome" class="login-label input-label">Username</label>
                    <input type="text" class="login-input" id="userNome" name="userNome">
                </div>

                <div class="input-container">
                    <label for="userEmail" class="login-label input-label">E-mail</label>
                    <input type="text" class="login-input" id="userEmail" name="userEmail">
                </div>

                <div class="input-container">
                    <label for="userSenha" class="login-label input-label">Password</label>
                    <input type="password" class="login-input" id="userSenha" name="userSenha">
                </div>

                <div class="input-container">
                    <label for="userSenhaConf" class="login-label input-label">Confirm Password</label>
                    <input type="password" class="login-input" id="userSenhaConf" name="userSenhaConf">
                </div>

            </div>

            <div class="input-section">
                <img id="imagePreview" src="" alt="Image Preview" style="display: none; max-width: 300px; margin-top: 10px; margin-left: auto; margin-right: auto;">

                <div class="input-container">
                    <label for="userFoto" class="login-label input-label input-file-label">Profile Picture</label>
                    <input type="file" class="login-input" id="userFoto" name="userFoto" accept="image/png, image/jpeg, image/webp">
                </div>
            </div>

            </div>

            <button type="submit" class="btn btn-primary input-btn ">Register</button>

            <a class="login-link login-link" href="/login">Return to Login Screen</a>
        </form>
    </section>
</body>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js" integrity="sha384-FKyoEForCGlyvwx9Hj09JcYn3nv7wiPVlz7YYwJrWVcXK/BmnVDxM+D2scQbITxI" crossorigin="anonymous"></script>
